using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace Icons
{
    /// <summary>
    /// The tile XrmToolBox shows. The two images are generated by tools\make-tool-icon.ps1,
    /// which draws them with this tool's own renderer - so the tool's own icon is the first
    /// thing that would look wrong if the renderer broke.
    /// </summary>
    [Export(typeof(IXrmToolBoxPlugin))]
    [ExportMetadata("Name", "Icons")]
    [ExportMetadata("Description", "Search a bundled library of Fluent, Phosphor, Lucide, Tabler, Font Awesome and Solar icons and set one as a Dataverse table icon, web resource and publish included")]
    [ExportMetadata("SmallImageBase64", "")]
    [ExportMetadata("BigImageBase64", "")]
    [ExportMetadata("BackgroundColor", "#F2F3EC")]
    [ExportMetadata("PrimaryFontColor", "#222512")]
    [ExportMetadata("SecondaryFontColor", "#5F673E")]
    public class IconsPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new IconsControl();
        }
    }
}
